const gcd=(a,b)=>b?gcd(b,a%b):a;
export function timetableLayout(sessions,getDay,getTime){let start=510,end=1230,step=30;const entries=sessions.map(event=>{const minute=value=>{const [h,m]=getTime(value).split(':').map(Number);return h*60+m};const from=minute(event.starts_at);let until=minute(event.ends_at);if(until<=from)until+=1440;start=Math.min(start,Math.floor(from/30)*30);end=Math.max(end,Math.ceil(until/30)*30);return {event,date:getDay(event.starts_at),from,until}});for(const e of entries){step=gcd(step,e.from-start);step=gcd(step,e.until-start)}step=Math.max(1,step);const slots=(end-start)/step,days=new Map();for(const e of entries.sort((a,b)=>a.from-b.from)){if(!days.has(e.date))days.set(e.date,[]);let lanes=days.get(e.date),lane=lanes.find(l=>l.at(-1).until<=e.from);if(!lane){lane=[];lanes.push(lane)}lane.push(e)}return {start,end,step,slots,days}}
export function rowCells(lane,layout){let cursor=layout.start;const cells=[];for(const entry of lane){if(entry.from>cursor)cells.push({span:(entry.from-cursor)/layout.step});cells.push({span:(entry.until-entry.from)/layout.step,event:entry.event});cursor=entry.until}if(cursor<layout.end)cells.push({span:(layout.end-cursor)/layout.step});return cells}
export const clockLabel=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
